#!/usr/bin/env python3
"""Reproduce the preregistered activation-linearity smoking-gun experiment.

All scientific trajectories are generated by the frozen command-line runners
in ``source/``.  This file only validates inputs, schedules those subprocesses,
checks completed archives, and writes deterministic provenance seals.

Resume policy
-------------
A completed job is skipped only when exactly one archive has the job's logical
identity, every frozen metadata field agrees, its time grid and array shapes
are exact, and every numeric array is finite.  A colliding-but-different
archive, duplicate match, partial archive, changed source/protocol file, or
changed seal is a hard error.
"""

from __future__ import annotations

import argparse
from concurrent.futures import ThreadPoolExecutor, as_completed
from dataclasses import dataclass
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys
import tempfile
from typing import Any, Callable, Iterable, Mapping, Sequence
import zipfile

import numpy as np


ROOT = Path(__file__).resolve().parent
REPO_ROOT = ROOT.parents[1]
HISTORICAL_ROOT = REPO_ROOT / "data/historical/studies/resnet_activation_controls"
SOURCE = ROOT / "source"
PROTOCOL_DIR = ROOT / "protocol"
PROTOCOL_PATH = PROTOCOL_DIR / "preregistered_protocol.json"
CASES_PATH = PROTOCOL_DIR / "cases.json"
RESULTS = REPO_ROOT / "data/generated/resnet_activation_controls/results"
PDE_DIR = RESULTS / "pde"
DENSE_DIR = RESULTS / "dense"
PROCESSED_DIR = RESULTS / "processed"
INPUT_MANIFEST_PATH = RESULTS / "FROZEN_INPUTS.json"
HISTORICAL_INPUT_MANIFEST_PATH = HISTORICAL_ROOT / "evidence/seals/FROZEN_INPUTS.json"
PDE_SEAL_PATH = RESULTS / "PDE_STAGE_SEAL.json"
DENSE_SEAL_PATH = RESULTS / "DENSE_STAGE_SEAL.json"
PYTHON = sys.executable

PRIMARY_CASES = ("C0", "C1", "C2", "C4", "L2")
SCRAMBLE_CASES = ("C0", "C2", "C4", "L2")
DEPTH_CASES = ("C0", "C2")
PARENT_RELEASE = (
    HISTORICAL_ROOT
    / "parent"
    / "dense_mup_pde_generalization_repro.zip"
)
PARENT_RELEASE_SHA256 = (
    "8e66e442fb322380acce93a0b59da4851a319401a087bb4b3e3146ed0c1de003"
)
PARENT_ZIP_PREFIX = "dense_mup_pde_generalization_repro/study/"
ALLOWED_SOURCE_PATCHES = frozenset(
    {
        "source/run_pde.py",
        "source/run_exact_reference.py",
        "source/src/activations.py",
        "source/src/study_cases.py",
    }
)


class IntegrityError(RuntimeError):
    """Raised when frozen inputs or resumable evidence do not agree."""


def _canonical_json(value: object) -> str:
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    )


def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def _map_sha256(files: Mapping[str, str]) -> str:
    return hashlib.sha256(_canonical_json(files).encode()).hexdigest()


def _relative(path: Path) -> str:
    return os.fspath(path.resolve().relative_to(ROOT.resolve()))


def _evidence_relative(path: Path) -> str:
    return os.fspath(path.resolve().relative_to(RESULTS.parent.resolve()))


def _source_files() -> dict[str, str]:
    files: dict[str, str] = {}
    for path in sorted(SOURCE.rglob("*")):
        if (
            path.is_file()
            and "__pycache__" not in path.parts
            and path.suffix not in {".pyc", ".pyo"}
        ):
            files[_relative(path)] = _sha256(path)
    if not files:
        raise IntegrityError("the frozen source tree is empty")
    return files


def _protocol_files() -> dict[str, str]:
    paths = (PROTOCOL_PATH, CASES_PATH)
    missing = [os.fspath(path) for path in paths if not path.is_file()]
    if missing:
        raise IntegrityError(f"missing frozen protocol files: {missing}")
    return {_relative(path): _sha256(path) for path in paths}


def _execution_files() -> dict[str, str]:
    paths = (
        Path(__file__),
        ROOT / "analyze_activation.py",
        ROOT / "tests" / "test_extension.py",
        ROOT / "requirements-lock.txt",
    )
    missing = [os.fspath(path) for path in paths if not path.is_file()]
    if missing:
        raise IntegrityError(
            "cannot freeze before all runner/analyzer/test files exist: "
            f"{missing}"
        )
    return {_relative(path): _sha256(path) for path in paths}


def _parent_source_lineage(
    current_files: Mapping[str, str],
) -> dict[str, Any]:
    if not PARENT_RELEASE.is_file():
        raise IntegrityError(f"missing recovered parent release: {PARENT_RELEASE}")
    observed_release_hash = _sha256(PARENT_RELEASE)
    if observed_release_hash != PARENT_RELEASE_SHA256:
        raise IntegrityError(
            "recovered parent release hash does not match the audited release"
        )
    records: dict[str, dict[str, Any]] = {}
    with zipfile.ZipFile(PARENT_RELEASE) as archive:
        members = set(archive.namelist())
        for current_relative, current_sha256 in current_files.items():
            source_relative = Path(current_relative).relative_to("source")
            if os.fspath(source_relative) == "operator_galerkin_pde.md":
                parent_suffix = "theory/operator_galerkin_pde.md"
            else:
                parent_suffix = source_relative.as_posix()
            member = PARENT_ZIP_PREFIX + parent_suffix
            if member in members:
                parent_sha256 = hashlib.sha256(archive.read(member)).hexdigest()
                status = (
                    "unchanged"
                    if parent_sha256 == current_sha256
                    else "modified"
                )
                records[current_relative] = {
                    "status": status,
                    "parent_zip_member": member,
                    "parent_sha256": parent_sha256,
                    "current_sha256": current_sha256,
                }
            else:
                records[current_relative] = {
                    "status": "new",
                    "parent_zip_member": None,
                    "parent_sha256": None,
                    "current_sha256": current_sha256,
                }
    modified = {
        relative
        for relative, record in records.items()
        if record["status"] == "modified"
    }
    new = {
        relative
        for relative, record in records.items()
        if record["status"] == "new"
    }
    if modified != ALLOWED_SOURCE_PATCHES:
        raise IntegrityError(
            "scientific source patch surface changed: "
            f"observed modified={sorted(modified)}, "
            f"allowed={sorted(ALLOWED_SOURCE_PATCHES)}"
        )
    if new:
        raise IntegrityError(
            f"unexpected new files in scientific source tree: {sorted(new)}"
        )
    return {
        "parent_release_path": os.fspath(
            os.path.relpath(PARENT_RELEASE, ROOT)
        ),
        "parent_release_sha256": observed_release_hash,
        "expected_parent_release_sha256": PARENT_RELEASE_SHA256,
        "files": records,
        "patch_set_sha256": hashlib.sha256(
            _canonical_json(records).encode()
        ).hexdigest(),
    }


def _input_record() -> dict[str, Any]:
    source_files = _source_files()
    protocol_files = _protocol_files()
    execution_files = _execution_files()
    lineage = _parent_source_lineage(source_files)
    return {
        "schema_version": 1,
        "stage": "activation_linearity_frozen_inputs",
        "source_files": source_files,
        "source_sha256": _map_sha256(source_files),
        "dynamics_sha256": _map_sha256(source_files),
        "protocol_files": protocol_files,
        "protocol_sha256": _map_sha256(protocol_files),
        "execution_files": execution_files,
        "execution_sha256": _map_sha256(execution_files),
        "parent_source_lineage": lineage,
        "inference_roles": {
            "confirmatory_activation_case": "C2",
            "descriptive_activation_cases": ["C1", "C4"],
            "identity_null_case": "C0",
            "first_hermite_null_case": "L2",
        },
        "orchestrator_sha256": _sha256(Path(__file__)),
    }


def _encoded(record: Mapping[str, Any]) -> str:
    return json.dumps(record, indent=2, sort_keys=True, allow_nan=False) + "\n"


def _write_once(path: Path, record: Mapping[str, Any]) -> None:
    encoded = _encoded(record)
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        if path.read_text() != encoded:
            raise IntegrityError(f"refusing to overwrite changed record: {path}")
        return
    partial = path.with_suffix(path.suffix + ".partial")
    if partial.exists():
        raise IntegrityError(f"stale partial record blocks write: {partial}")
    with partial.open("w") as handle:
        handle.write(encoded)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(partial, path)


def _create_input_manifest() -> dict[str, Any]:
    if HISTORICAL_INPUT_MANIFEST_PATH.is_file() and not INPUT_MANIFEST_PATH.exists():
        raise IntegrityError(
            "the retained seal is historical; migration does not authorize "
            "regenerating FROZEN_INPUTS.json"
        )
    record = _input_record()
    if not INPUT_MANIFEST_PATH.exists() and RESULTS.exists():
        preexisting = sorted(
            path
            for path in RESULTS.rglob("*")
            if path.is_file()
        )
        if preexisting:
            raise IntegrityError(
                "refusing first freeze after result files already exist: "
                + ", ".join(os.fspath(path) for path in preexisting)
            )
    _write_once(INPUT_MANIFEST_PATH, record)
    return record


def _require_input_manifest() -> dict[str, Any]:
    if not INPUT_MANIFEST_PATH.is_file():
        raise IntegrityError(
            "missing live FROZEN_INPUTS.json; the historical seal at "
            f"{HISTORICAL_INPUT_MANIFEST_PATH} is not current execution authorization"
        )
    stored = json.loads(INPUT_MANIFEST_PATH.read_text())
    current = _input_record()
    if stored != current:
        raise IntegrityError("source, protocol, or orchestrator changed after freeze")
    return stored


def _load_protocol() -> tuple[dict[str, Any], dict[str, Any]]:
    protocol = json.loads(PROTOCOL_PATH.read_text())
    cases = json.loads(CASES_PATH.read_text())
    return protocol, cases


def _case_hash(case_id: str, case: Mapping[str, Any]) -> str:
    payload = {
        "case_id": case_id,
        "X": case["X"],
        "y": case["y"],
        "activation": case["activation"],
        "sigma_w": case["sigma_w"],
        "A": case["A"],
        "gamma": case["gamma"],
    }
    return hashlib.sha256(_canonical_json(payload).encode()).hexdigest()


def _case_metadata(
    case_id: str,
    cases_document: Mapping[str, Any],
) -> dict[str, Any]:
    case = cases_document["cases"][case_id]
    return {
        "case_id": case_id,
        "case_sha256": _case_hash(case_id, case),
        "registry_sha256": _sha256(CASES_PATH),
        "activation": case["activation"],
        "X": case["X"],
        "y": case["y"],
        "sigma_w": case["sigma_w"],
        "A": case["A"],
        "gamma": case["gamma"],
    }


def _metadata(path: Path) -> dict[str, Any]:
    try:
        with np.load(path, allow_pickle=False) as archive:
            if "metadata_json" not in archive:
                raise IntegrityError(f"{path}: missing metadata_json")
            return json.loads(str(archive["metadata_json"]))
    except IntegrityError:
        raise
    except Exception as exc:
        raise IntegrityError(f"cannot read archive metadata from {path}") from exc


def _equal(left: Any, right: Any) -> bool:
    if isinstance(left, (list, tuple)) or isinstance(right, (list, tuple)):
        try:
            return bool(np.array_equal(np.asarray(left), np.asarray(right)))
        except (TypeError, ValueError):
            return left == right
    if isinstance(left, (int, float)) and isinstance(right, (int, float)):
        return bool(float(left) == float(right))
    return bool(left == right)


def _require_metadata(
    path: Path,
    metadata: Mapping[str, Any],
    expected: Mapping[str, Any],
) -> None:
    for key, value in expected.items():
        if key not in metadata:
            raise IntegrityError(f"{path}: missing metadata field {key!r}")
        if not _equal(metadata[key], value):
            raise IntegrityError(
                f"{path}: metadata mismatch for {key!r}: "
                f"{metadata[key]!r} != {value!r}"
            )


def _expected_times(duration: float, sample_dt: float) -> np.ndarray:
    count = int(round(duration / sample_dt)) + 1
    return np.arange(count, dtype=float) * sample_dt


def _require_finite(
    path: Path,
    archive: np.lib.npyio.NpzFile,
    names: Iterable[str],
) -> None:
    for name in names:
        if name not in archive:
            raise IntegrityError(f"{path}: missing array {name!r}")
        if not np.all(np.isfinite(archive[name])):
            raise IntegrityError(f"{path}: nonfinite values in {name!r}")


def _validate_pde_archive(
    path: Path,
    expected: Mapping[str, Any],
) -> dict[str, Any]:
    metadata = _metadata(path)
    _require_metadata(path, metadata, expected)
    nt = _expected_times(
        float(expected["duration"]),
        float(expected["sample_dt"]),
    ).size
    m = len(expected["y"])
    n_depth = int(expected["depth_nodes_N"])
    M = int(expected["base_quadrature_M"])
    R = int(expected["fast_quadrature_R"])
    P = int(expected["basis_size_P"])
    shapes = {
        "times": (nt,),
        "f": (nt, m),
        "loss": (nt,),
        "grams": (nt, n_depth + 1, m, m),
        "theta": (nt, m, m),
        "theta_min": (nt,),
        "residual_norm": (nt,),
        "loss_dot": (nt,),
        "projected_energy": (nt, n_depth, m),
        "final_B": (M, len(expected["X"])),
        "final_a": (M,),
        "final_c": (n_depth, M, R, P),
    }
    with np.load(path, allow_pickle=False) as archive:
        _require_finite(path, archive, shapes)
        for name, shape in shapes.items():
            if archive[name].shape != shape:
                raise IntegrityError(
                    f"{path}: {name} shape {archive[name].shape} != {shape}"
                )
        np.testing.assert_array_equal(
            archive["times"],
            _expected_times(
                float(expected["duration"]),
                float(expected["sample_dt"]),
            ),
            err_msg=f"{path}: unexpected PDE time grid",
        )
    return metadata


def _validate_dense_archive(
    path: Path,
    expected: Mapping[str, Any],
) -> dict[str, Any]:
    metadata = _metadata(path)
    _require_metadata(path, metadata, expected)
    nt = _expected_times(
        float(expected["duration"]),
        float(expected["sample_dt"]),
    ).size
    members = int(expected["seeds"])
    depth = int(expected["depth"])
    m = len(expected["y"])
    shapes = {
        "times": (nt,),
        "seeds": (members,),
        "f": (members, nt, m),
        "grams": (members, nt, depth + 1, m, m),
        "theta": (members, nt, m, m),
        "f_mean": (nt, m),
        "f_sem": (nt, m),
        "grams_mean": (nt, depth + 1, m, m),
        "grams_sem": (nt, depth + 1, m, m),
        "theta_mean": (nt, m, m),
        "theta_sem": (nt, m, m),
    }
    with np.load(path, allow_pickle=False) as archive:
        _require_finite(path, archive, shapes)
        for name, shape in shapes.items():
            if archive[name].shape != shape:
                raise IntegrityError(
                    f"{path}: {name} shape {archive[name].shape} != {shape}"
                )
        np.testing.assert_array_equal(
            archive["times"],
            _expected_times(
                float(expected["duration"]),
                float(expected["sample_dt"]),
            ),
            err_msg=f"{path}: unexpected dense time grid",
        )
        np.testing.assert_array_equal(
            archive["seeds"],
            np.arange(
                int(expected["seed_start"]),
                int(expected["seed_start"]) + members,
            ),
            err_msg=f"{path}: unexpected dense seed vector",
        )
    return metadata


@dataclass(frozen=True)
class Job:
    role: str
    case_id: str
    command: tuple[str, ...]
    output_dir: Path
    expected: Mapping[str, Any]
    collision: Callable[[Mapping[str, Any]], bool]
    validator: Callable[[Path, Mapping[str, Any]], Mapping[str, Any]]


def _pde_collision(expected: Mapping[str, Any]) -> Callable[[Mapping[str, Any]], bool]:
    keys = ("case_id", "quadrature_seed", "depth_nodes_N")

    def collides(metadata: Mapping[str, Any]) -> bool:
        return all(
            key in metadata and _equal(metadata[key], expected[key])
            for key in keys
        )

    return collides


def _dense_collision(
    expected: Mapping[str, Any],
) -> Callable[[Mapping[str, Any]], bool]:
    keys = ("case_id", "n", "depth", "seeds", "seed_start")

    def collides(metadata: Mapping[str, Any]) -> bool:
        return all(
            key in metadata and _equal(metadata[key], expected[key])
            for key in keys
        )

    return collides


def _pde_jobs(role: str) -> list[Job]:
    protocol, cases_document = _load_protocol()
    fixed = protocol["pde"]
    if role == "primary":
        case_ids = PRIMARY_CASES
        seed = int(fixed["seed"])
        N = int(fixed["N"])
    elif role == "scramble":
        case_ids = SCRAMBLE_CASES
        seed = int(protocol["pde_numerical_controls"]["independent_scramble_seed"])
        N = int(fixed["N"])
    elif role == "N32":
        case_ids = tuple(protocol["pde_depth_control"]["cases"])
        seed = int(fixed["seed"])
        N = int(protocol["pde_depth_control"]["N"])
    else:
        raise ValueError(f"unknown PDE role {role!r}")

    jobs: list[Job] = []
    for case_id in case_ids:
        case_meta = _case_metadata(case_id, cases_document)
        expected = {
            **case_meta,
            "quadrature": fixed["quadrature"],
            "base_order": int(fixed["base_order"]),
            "basis_size_P": int(fixed["P"]),
            "depth_nodes_N": N,
            "base_quadrature_M": int(fixed["M"]),
            "fast_quadrature_R": int(fixed["R"]),
            "quadrature_seed": seed,
            "integrator": fixed["integrator"],
            "duration": float(fixed["duration"]),
            "start_time": 0.0,
            "end_time": float(fixed["duration"]),
            "dt": float(fixed["dt"]),
            "sample_dt": float(fixed["sample_dt"]),
        }
        command = (
            PYTHON,
            os.fspath(SOURCE / "run_pde.py"),
            "--case-registry",
            os.fspath(CASES_PATH),
            "--case-id",
            case_id,
            "--quadrature",
            str(fixed["quadrature"]),
            "--base-order",
            str(fixed["base_order"]),
            "--P",
            str(fixed["P"]),
            "--N",
            str(N),
            "--M",
            str(fixed["M"]),
            "--R",
            str(fixed["R"]),
            "--seed",
            str(seed),
            "--integrator",
            str(fixed["integrator"]),
            "--dt",
            str(fixed["dt"]),
            "--sample-dt",
            str(fixed["sample_dt"]),
            "--duration",
            str(fixed["duration"]),
            "--output-dir",
            os.fspath(PDE_DIR),
        )
        jobs.append(
            Job(
                role=role,
                case_id=case_id,
                command=command,
                output_dir=PDE_DIR,
                expected=expected,
                collision=_pde_collision(expected),
                validator=_validate_pde_archive,
            )
        )
    return jobs


def _dense_jobs(role: str) -> list[Job]:
    protocol, cases_document = _load_protocol()
    if role == "primary":
        case_ids = PRIMARY_CASES
        tier = protocol["dense_reference"]
        depth = int(tier["depth"])
    elif role == "physical_depth":
        case_ids = DEPTH_CASES
        tier = protocol["physical_depth_control"]
        depth = int(tier["depth"])
    elif role == "width":
        case_ids = tuple(protocol["physical_width_control"]["cases"])
        tier = protocol["physical_width_control"]
        depth = int(tier["depth"])
    else:
        raise ValueError(f"unknown dense role {role!r}")

    seal = _require_pde_seal()
    pde_seal_sha256 = _sha256(PDE_SEAL_PATH)
    jobs: list[Job] = []
    for case_id in case_ids:
        case_meta = _case_metadata(case_id, cases_document)
        expected = {
            **case_meta,
            "n": int(tier["n"]),
            "depth": depth,
            "seeds": int(tier["seeds"]),
            "seed_start": int(tier["seed_start"]),
            "duration": float(tier["duration"]),
            "dt": float(tier["dt"]),
            "sample_dt": float(tier["sample_dt"]),
            "pde_seal_sha256": pde_seal_sha256,
            "dynamics_sha256": seal["dynamics_sha256"],
        }
        command = (
            PYTHON,
            os.fspath(SOURCE / "run_exact_reference.py"),
            "--case-registry",
            os.fspath(CASES_PATH),
            "--case-id",
            case_id,
            "--n",
            str(tier["n"]),
            "--depth",
            str(depth),
            "--seeds",
            str(tier["seeds"]),
            "--seed-start",
            str(tier["seed_start"]),
            "--workers",
            "{dense_workers}",
            "--duration",
            str(tier["duration"]),
            "--dt",
            str(tier["dt"]),
            "--sample-dt",
            str(tier["sample_dt"]),
            "--output-dir",
            os.fspath(DENSE_DIR),
            "--pde-seal",
            os.fspath(PDE_SEAL_PATH),
        )
        jobs.append(
            Job(
                role=role,
                case_id=case_id,
                command=command,
                output_dir=DENSE_DIR,
                expected=expected,
                collision=_dense_collision(expected),
                validator=_validate_dense_archive,
            )
        )
    return jobs


def _partials(directory: Path) -> list[Path]:
    if not directory.exists():
        return []
    return sorted(directory.glob("*.partial"))


def _find_completed(job: Job) -> Path | None:
    partials = _partials(job.output_dir)
    if partials:
        raise IntegrityError(
            "partial archives block safe resume: "
            + ", ".join(os.fspath(path) for path in partials)
        )
    matches: list[Path] = []
    for path in sorted(job.output_dir.glob("*.npz")):
        metadata = _metadata(path)
        if job.collision(metadata):
            job.validator(path, job.expected)
            matches.append(path)
    if len(matches) > 1:
        raise IntegrityError(
            f"duplicate archives for {job.role}/{job.case_id}: {matches}"
        )
    return matches[0] if matches else None


def _subprocess_env() -> dict[str, str]:
    env = os.environ.copy()
    env["PYTHONPATH"] = os.fspath(SOURCE / "src")
    env["OPENBLAS_NUM_THREADS"] = "1"
    env["OMP_NUM_THREADS"] = "1"
    env["MKL_NUM_THREADS"] = "1"
    env["NUMEXPR_NUM_THREADS"] = "1"
    env.setdefault(
        "MPLCONFIGDIR",
        os.path.join(tempfile.gettempdir(), "activation-linearity-matplotlib"),
    )
    return env


def _run_command(
    command: Sequence[str],
    label: str,
    *,
    env: Mapping[str, str] | None = None,
) -> str:
    print("+", " ".join(command), flush=True)
    completed = subprocess.run(
        list(command),
        cwd=ROOT,
        env=dict(env) if env is not None else _subprocess_env(),
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        check=False,
    )
    if completed.returncode:
        raise RuntimeError(
            f"{label} failed with code {completed.returncode}\n"
            f"{completed.stdout}"
        )
    lines = completed.stdout.strip().splitlines()
    return f"{label}: {lines[-1] if lines else 'complete'}"


def _run_one(job: Job, dense_workers: int) -> str:
    _require_input_manifest()
    completed = _find_completed(job)
    if completed is not None:
        return f"{job.role} {job.case_id}: resume verified {completed.name}"
    job.output_dir.mkdir(parents=True, exist_ok=True)
    command = tuple(
        str(dense_workers) if value == "{dense_workers}" else value
        for value in job.command
    )
    message = _run_command(command, f"{job.role} {job.case_id}")
    _require_input_manifest()
    completed = _find_completed(job)
    if completed is None:
        raise IntegrityError(
            f"{job.role}/{job.case_id} subprocess created no matching archive"
        )
    return f"{message}; verified {completed.name}"


def _run_jobs(
    jobs: Sequence[Job],
    *,
    parallel_jobs: int,
    dense_workers: int,
) -> None:
    if parallel_jobs < 1 or dense_workers < 1:
        raise ValueError("parallel_jobs and dense_workers must be positive")
    with ThreadPoolExecutor(max_workers=parallel_jobs) as pool:
        futures = {
            pool.submit(_run_one, job, dense_workers): job
            for job in jobs
        }
        for future in as_completed(futures):
            print(future.result(), flush=True)


def _exact_inventory(
    jobs: Sequence[Job],
    directory: Path,
) -> list[tuple[Job, Path]]:
    partials = _partials(directory)
    if partials:
        raise IntegrityError(f"partial archives present in {directory}: {partials}")
    records: list[tuple[Job, Path]] = []
    for job in jobs:
        path = _find_completed(job)
        if path is None:
            raise IntegrityError(
                f"missing expected archive for {job.role}/{job.case_id}"
            )
        records.append((job, path))
    expected_paths = {path.resolve() for _, path in records}
    actual_paths = {path.resolve() for path in directory.glob("*.npz")}
    if actual_paths != expected_paths:
        extras = sorted(os.fspath(path) for path in actual_paths - expected_paths)
        missing = sorted(os.fspath(path) for path in expected_paths - actual_paths)
        raise IntegrityError(
            f"archive inventory mismatch in {directory}: "
            f"extras={extras}, missing={missing}"
        )
    return records


def _all_pde_jobs() -> list[Job]:
    return _pde_jobs("primary") + _pde_jobs("scramble") + _pde_jobs("N32")


def _all_dense_jobs() -> list[Job]:
    return (
        _dense_jobs("primary")
        + _dense_jobs("physical_depth")
        + _dense_jobs("width")
    )


def _require_seal_common(record: Mapping[str, Any], stage: str) -> None:
    inputs = _require_input_manifest()
    required = {
        "schema_version": 1,
        "stage": stage,
        "dynamics_sha256": inputs["dynamics_sha256"],
        "source_sha256": inputs["source_sha256"],
        "source_files": inputs["source_files"],
        "protocol_sha256": inputs["protocol_sha256"],
        "protocol_files": inputs["protocol_files"],
        "execution_sha256": inputs["execution_sha256"],
        "execution_files": inputs["execution_files"],
        "parent_source_lineage": inputs["parent_source_lineage"],
        "inference_roles": inputs["inference_roles"],
        "input_manifest_sha256": _sha256(INPUT_MANIFEST_PATH),
        "orchestrator_sha256": _sha256(Path(__file__)),
    }
    for key, value in required.items():
        if record.get(key) != value:
            raise IntegrityError(f"{stage} seal mismatch for {key!r}")
    files = record.get("files")
    if not isinstance(files, dict):
        raise IntegrityError(f"{stage} seal has no file map")
    for relative, expected_sha256 in files.items():
        path = ROOT / relative
        if not path.is_file() or _sha256(path) != expected_sha256:
            raise IntegrityError(f"sealed file mismatch: {relative}")


def seal_pde() -> dict[str, Any]:
    inputs = _require_input_manifest()
    records = _exact_inventory(_all_pde_jobs(), PDE_DIR)
    files = {_evidence_relative(path): _sha256(path) for _, path in records}
    inventory = [
        {
            "role": job.role,
            "case_id": job.case_id,
            "N": int(job.expected["depth_nodes_N"]),
            "seed": int(job.expected["quadrature_seed"]),
            "path": _evidence_relative(path),
            "sha256": _sha256(path),
        }
        for job, path in records
    ]
    seal = {
        "schema_version": 1,
        "stage": "activation_linearity_pde",
        "dynamics_sha256": inputs["dynamics_sha256"],
        "source_sha256": inputs["source_sha256"],
        "source_files": inputs["source_files"],
        "protocol_sha256": inputs["protocol_sha256"],
        "protocol_files": inputs["protocol_files"],
        "execution_sha256": inputs["execution_sha256"],
        "execution_files": inputs["execution_files"],
        "parent_source_lineage": inputs["parent_source_lineage"],
        "inference_roles": inputs["inference_roles"],
        "input_manifest_sha256": _sha256(INPUT_MANIFEST_PATH),
        "orchestrator_sha256": _sha256(Path(__file__)),
        "files": files,
        "inventory": inventory,
        "file_count": len(files),
    }
    _write_once(PDE_SEAL_PATH, seal)
    print(_encoded(seal), end="")
    return seal


def _require_pde_seal() -> dict[str, Any]:
    if not PDE_SEAL_PATH.is_file():
        raise IntegrityError("dense stages require a completed PDE_STAGE_SEAL.json")
    record = json.loads(PDE_SEAL_PATH.read_text())
    _require_seal_common(record, "activation_linearity_pde")
    if record.get("file_count") != 11 or len(record.get("inventory", [])) != 11:
        raise IntegrityError("PDE seal has the wrong archive count")
    records = _exact_inventory(_all_pde_jobs(), PDE_DIR)
    observed = {_evidence_relative(path): _sha256(path) for _, path in records}
    if record["files"] != observed:
        raise IntegrityError("PDE seal inventory differs from current PDE evidence")
    return record


def seal_dense() -> dict[str, Any]:
    pde_seal = _require_pde_seal()
    inputs = _require_input_manifest()
    records = _exact_inventory(_all_dense_jobs(), DENSE_DIR)
    files = {_evidence_relative(path): _sha256(path) for _, path in records}
    inventory = [
        {
            "role": job.role,
            "case_id": job.case_id,
            "n": int(job.expected["n"]),
            "depth": int(job.expected["depth"]),
            "seeds": int(job.expected["seeds"]),
            "seed_start": int(job.expected["seed_start"]),
            "path": _evidence_relative(path),
            "sha256": _sha256(path),
        }
        for job, path in records
    ]
    seal = {
        "schema_version": 1,
        "stage": "activation_linearity_dense",
        "dynamics_sha256": inputs["dynamics_sha256"],
        "source_sha256": inputs["source_sha256"],
        "source_files": inputs["source_files"],
        "protocol_sha256": inputs["protocol_sha256"],
        "protocol_files": inputs["protocol_files"],
        "execution_sha256": inputs["execution_sha256"],
        "execution_files": inputs["execution_files"],
        "parent_source_lineage": inputs["parent_source_lineage"],
        "inference_roles": inputs["inference_roles"],
        "input_manifest_sha256": _sha256(INPUT_MANIFEST_PATH),
        "orchestrator_sha256": _sha256(Path(__file__)),
        "pde_seal_sha256": _sha256(PDE_SEAL_PATH),
        "files": files,
        "inventory": inventory,
        "file_count": len(files),
    }
    if pde_seal["dynamics_sha256"] != seal["dynamics_sha256"]:
        raise IntegrityError("PDE and dense source hashes differ")
    _write_once(DENSE_SEAL_PATH, seal)
    print(_encoded(seal), end="")
    return seal


def _require_dense_seal() -> dict[str, Any]:
    _require_pde_seal()
    if not DENSE_SEAL_PATH.is_file():
        raise IntegrityError("analysis requires DENSE_STAGE_SEAL.json")
    record = json.loads(DENSE_SEAL_PATH.read_text())
    _require_seal_common(record, "activation_linearity_dense")
    if record.get("pde_seal_sha256") != _sha256(PDE_SEAL_PATH):
        raise IntegrityError("dense seal points to a different PDE seal")
    if record.get("file_count") != 9 or len(record.get("inventory", [])) != 9:
        raise IntegrityError("dense seal has the wrong archive count")
    records = _exact_inventory(_all_dense_jobs(), DENSE_DIR)
    observed = {_evidence_relative(path): _sha256(path) for _, path in records}
    if record["files"] != observed:
        raise IntegrityError("dense seal differs from current dense evidence")
    return record


def validate_stage() -> None:
    _load_protocol()
    tests = (
        PYTHON,
        "-m",
        "unittest",
        "discover",
        "-s",
        os.fspath(ROOT / "tests"),
        "-p",
        "test_extension.py",
        "-v",
    )
    print(_run_command(tests, "extension validation"), flush=True)
    for script in (
        SOURCE / "run_pde.py",
        SOURCE / "run_exact_reference.py",
        ROOT / "analyze_activation.py",
    ):
        print(
            _run_command(
                (PYTHON, os.fspath(script), "--help"),
                f"{script.name} CLI validation",
            ),
            flush=True,
        )
    record = _create_input_manifest()
    print(
        "frozen input manifest:",
        INPUT_MANIFEST_PATH,
        record["dynamics_sha256"],
        flush=True,
    )


def analyze_stage() -> None:
    _require_dense_seal()
    analyzer = ROOT / "analyze_activation.py"
    if not analyzer.is_file():
        raise IntegrityError(f"missing analyzer: {analyzer}")
    command = (
        PYTHON,
        os.fspath(analyzer),
        "--root",
        os.fspath(ROOT),
        "--protocol",
        os.fspath(PROTOCOL_PATH),
        "--cases",
        os.fspath(CASES_PATH),
        "--pde-dir",
        os.fspath(PDE_DIR),
        "--dense-dir",
        os.fspath(DENSE_DIR),
        "--output-dir",
        os.fspath(PROCESSED_DIR),
    )
    print(_run_command(command, "activation analysis"), flush=True)


def run_stage(args: argparse.Namespace) -> None:
    if getattr(args, "historical_status", False):
        print(json.dumps({
            "status": "historical_only",
            "current_execution_authorized": False,
            "seal_path": str(HISTORICAL_INPUT_MANIFEST_PATH),
            "seal_exists": HISTORICAL_INPUT_MANIFEST_PATH.is_file(),
            "seal_sha256": _sha256(HISTORICAL_INPUT_MANIFEST_PATH)
            if HISTORICAL_INPUT_MANIFEST_PATH.is_file() else None,
        }, sort_keys=True))
        return
    if args.stage == "validate":
        validate_stage()
    elif args.stage == "pde-primary":
        _run_jobs(
            _pde_jobs("primary"),
            parallel_jobs=args.parallel_pde,
            dense_workers=args.dense_workers,
        )
    elif args.stage == "pde-scramble":
        _run_jobs(
            _pde_jobs("scramble"),
            parallel_jobs=args.parallel_pde,
            dense_workers=args.dense_workers,
        )
    elif args.stage == "pde-n32":
        _run_jobs(
            _pde_jobs("N32"),
            parallel_jobs=args.parallel_pde,
            dense_workers=args.dense_workers,
        )
    elif args.stage == "seal-pde":
        seal_pde()
    elif args.stage == "dense-primary":
        _run_jobs(
            _dense_jobs("primary"),
            parallel_jobs=args.parallel_dense,
            dense_workers=args.dense_workers,
        )
    elif args.stage == "dense-depth":
        _run_jobs(
            _dense_jobs("physical_depth"),
            parallel_jobs=args.parallel_dense,
            dense_workers=args.dense_workers,
        )
    elif args.stage == "dense-width":
        _run_jobs(
            _dense_jobs("width"),
            parallel_jobs=args.parallel_dense,
            dense_workers=args.dense_workers,
        )
    elif args.stage == "seal-dense":
        seal_dense()
    elif args.stage == "analyze":
        analyze_stage()
    else:
        validate_stage()
        for role in ("primary", "scramble", "N32"):
            _run_jobs(
                _pde_jobs(role),
                parallel_jobs=args.parallel_pde,
                dense_workers=args.dense_workers,
            )
        seal_pde()
        for role in ("primary", "physical_depth", "width"):
            _run_jobs(
                _dense_jobs(role),
                parallel_jobs=args.parallel_dense,
                dense_workers=args.dense_workers,
            )
        seal_dense()
        analyze_stage()


def parse_args(argv: Sequence[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description=(
            "Run the frozen activation-linearity experiment with strict, "
            "metadata-validated resume."
        )
    )
    parser.add_argument(
        "stage",
        nargs="?",
        default="all",
        choices=(
            "all",
            "validate",
            "pde-primary",
            "pde-scramble",
            "pde-n32",
            "seal-pde",
            "dense-primary",
            "dense-depth",
            "dense-width",
            "seal-dense",
            "analyze",
        ),
    )
    parser.add_argument("--parallel-pde", type=int, default=3)
    parser.add_argument("--parallel-dense", type=int, default=1)
    parser.add_argument("--dense-workers", type=int, default=4)
    parser.add_argument("--historical-status", action="store_true",
                        help="Locate the unchanged historical seal without authorizing execution")
    return parser.parse_args(argv)


if __name__ == "__main__":
    run_stage(parse_args())

