"""Fail-closed protocol decision rules.

The numerical constants are never chosen here.  A frozen protocol must supply
``DecisionThresholds``; absent thresholds cannot silently inherit defaults in
scientific production.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Mapping

from .comparison import BracketComparison


@dataclass(frozen=True)
class DecisionThresholds:
    confidence: float
    maximum_reference_to_bracket_width_ratio: float | None
    maximum_width_model_log_disagreement: float
    maximum_width_fit_relative_residual: float
    maximum_bootstrap_invalid_fraction: float
    maximum_relative_standard_error: float
    maximum_relative_jensen_gap: float
    maximum_transverse_leakage: float | None
    require_scientific_admissibility: bool = True

    @classmethod
    def from_mapping(cls, values: Mapping[str, Any]) -> "DecisionThresholds":
        required = {
            "confidence",
            "maximum_reference_to_bracket_width_ratio",
            "maximum_width_model_log_disagreement",
            "maximum_width_fit_relative_residual",
            "maximum_bootstrap_invalid_fraction",
            "maximum_relative_standard_error",
            "maximum_relative_jensen_gap",
            "maximum_transverse_leakage",
        }
        missing = sorted(required - values.keys())
        if missing:
            raise ValueError(f"protocol decision thresholds are missing {missing}")
        return cls(
            confidence=float(values["confidence"]),
            maximum_reference_to_bracket_width_ratio=(
                None
                if values["maximum_reference_to_bracket_width_ratio"] is None
                else float(values["maximum_reference_to_bracket_width_ratio"])
            ),
            maximum_width_model_log_disagreement=float(
                values["maximum_width_model_log_disagreement"]
            ),
            maximum_width_fit_relative_residual=float(
                values["maximum_width_fit_relative_residual"]
            ),
            maximum_bootstrap_invalid_fraction=float(
                values["maximum_bootstrap_invalid_fraction"]
            ),
            maximum_relative_standard_error=float(
                values["maximum_relative_standard_error"]
            ),
            maximum_relative_jensen_gap=float(values["maximum_relative_jensen_gap"]),
            maximum_transverse_leakage=(
                None
                if values["maximum_transverse_leakage"] is None
                else float(values["maximum_transverse_leakage"])
            ),
            require_scientific_admissibility=bool(
                values.get("require_scientific_admissibility", True)
            ),
        )


@dataclass(frozen=True)
class Decision:
    status: str
    reason: str
    validity_gates: Mapping[str, bool]


def decide_bracket(
    bracket: BracketComparison,
    *,
    thresholds: DecisionThresholds,
    evidence_admissible: bool,
    bootstrap_confidence: float,
    bootstrap_invalid_fraction: float,
    maximum_relative_standard_error: float,
    maximum_relative_jensen_gap: float,
    maximum_width_model_log_disagreement: float,
    maximum_width_fit_relative_residual: float,
    transverse_leakage: float | None,
    two_largest_widths_repeat_escape: bool = True,
) -> Decision:
    """Apply numerical-validity gates before the scientific discriminator."""

    gates = {
        "scientific_evidence_admissible": (
            evidence_admissible or not thresholds.require_scientific_admissibility
        ),
        "confidence_matches_protocol": abs(
            bootstrap_confidence - thresholds.confidence
        ) <= 8.0e-15,
        "bootstrap_validity": (
            bootstrap_invalid_fraction
            <= thresholds.maximum_bootstrap_invalid_fraction
        ),
        "relative_standard_error": (
            maximum_relative_standard_error
            <= thresholds.maximum_relative_standard_error
        ),
        "jensen_gap": (
            maximum_relative_jensen_gap <= thresholds.maximum_relative_jensen_gap
        ),
        "width_model_sensitivity": (
            maximum_width_model_log_disagreement
            <= thresholds.maximum_width_model_log_disagreement
        ),
        "width_fit_residual": (
            maximum_width_fit_relative_residual
            <= thresholds.maximum_width_fit_relative_residual
        ),
        "transverse_leakage": (
            True
            if thresholds.maximum_transverse_leakage is None
            else transverse_leakage is not None
            and transverse_leakage <= thresholds.maximum_transverse_leakage
        ),
    }
    failed_gates = [name for name, passed in gates.items() if not passed]
    if failed_gates:
        return Decision(
            "inconclusive",
            "numerical validity gate failed: " + ", ".join(failed_gates),
            gates,
        )
    if bracket.containment_status == "fail":
        if not two_largest_widths_repeat_escape:
            return Decision(
                "inconclusive",
                "extrapolated escape is not repeated with the same sign at both largest widths",
                gates,
            )
        return Decision(
            "fail",
            "the simultaneous reference band is definitely outside the proxy bracket",
            gates,
        )
    if bracket.containment_status != "pass":
        return Decision(
            "inconclusive",
            "the simultaneous reference band overlaps a proxy boundary",
            gates,
        )
    if (
        thresholds.maximum_reference_to_bracket_width_ratio is not None
        and bracket.reference_to_bracket_width_ratio
        > thresholds.maximum_reference_to_bracket_width_ratio
    ):
        return Decision(
            "inconclusive",
            "reference uncertainty is too large relative to this proxy bracket",
            gates,
        )
    return Decision(
        "pass",
        "the resolved simultaneous reference band is contained in the proxy bracket",
        gates,
    )


def decide_protocol_bracket(
    bracket: BracketComparison,
    *,
    validity_gates: Mapping[str, bool],
    two_largest_escape_directions: tuple[str, str] | None,
) -> Decision:
    """Apply the frozen protocol's exact prefix classifier.

    ``pass`` means protocol-compatible, while ``fail`` means protocol-contrary.
    A definite extrapolated escape is still inconclusive unless the two
    largest valid finite widths repeat the same nonzero signed escape.
    """

    failed = [name for name, passed in validity_gates.items() if not passed]
    if failed:
        return Decision(
            "inconclusive",
            "mandatory protocol gate failed: " + ", ".join(failed),
            validity_gates,
        )
    if bracket.containment_status == "pass":
        return Decision(
            "pass",
            "complete 99% simultaneous sensitivity-union band is inside the bracket",
            validity_gates,
        )
    if bracket.containment_status != "fail":
        return Decision(
            "inconclusive",
            "reference band overlaps at least one rational boundary",
            validity_gates,
        )
    if two_largest_escape_directions is None:
        return Decision(
            "inconclusive",
            "two-largest-width signed escape confirmation is unavailable",
            validity_gates,
        )
    left, right = two_largest_escape_directions
    if left == right == bracket.definite_escape_direction and left in {"above", "below"}:
        return Decision(
            "fail",
            "same signed bracket escape occurs in the union and both largest widths",
            validity_gates,
        )
    return Decision(
        "inconclusive",
        "same signed escape is absent at one or both largest widths",
        validity_gates,
    )

"""Prespecified width-limit fits and sensitivity diagnostics."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Iterable, Literal, Sequence

import numpy as np

from .bootstrap import BootstrapBand, PointBootstrap, simultaneous_log_band


WidthModel = Literal[
    "inv_n_all",
    "inv_sqrt_n_all",
    "inv_n_leave_smallest",
    "inv_n_top3",
    "top_width_direct",
]


@dataclass(frozen=True)
class WidthEstimate:
    model: WidthModel
    widths_used: tuple[int, ...]
    output: np.ndarray
    band: BootstrapBand
    samples: np.ndarray
    maximum_relative_fit_residual: float

    def compact_record(self) -> dict[str, Any]:
        return {
            "model": self.model,
            "widths_used": list(self.widths_used),
            "output": self.output.tolist(),
            "band": self.band.record(),
            "maximum_relative_fit_residual": self.maximum_relative_fit_residual,
        }


@dataclass(frozen=True)
class UnionWidthReference:
    """Conservative union of all prespecified width-sensitivity bands."""

    primary_model: WidthModel
    component_models: tuple[WidthModel, ...]
    output: np.ndarray
    band: BootstrapBand

    def compact_record(self) -> dict[str, Any]:
        return {
            "primary_model": self.primary_model,
            "component_models": list(self.component_models),
            "output": self.output.tolist(),
            "band": self.band.record(),
        }


def _validate_points(points: Sequence[PointBootstrap]) -> tuple[PointBootstrap, ...]:
    points = tuple(sorted(points, key=lambda point: point.width))
    if len(points) < 2:
        raise ValueError("width extrapolation requires at least two widths")
    widths = [point.width for point in points]
    if len(set(widths)) != len(widths):
        raise ValueError("widths must be unique within an extrapolation group")
    first = points[0].output
    for point in points[1:]:
        if not np.array_equal(first, point.output):
            raise ValueError("all width points must use the identical output grid")
        if point.band.confidence != points[0].band.confidence:
            raise ValueError("all width bootstraps must use the same confidence")
    return points


def _fit_intercept(values: np.ndarray, x: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    """Fit values[width,grid] = intercept[grid] + slope[grid] * x."""

    design = np.column_stack((np.ones(len(x)), x))
    coefficients = np.linalg.pinv(design) @ values
    fitted = design @ coefficients
    return coefficients[0], fitted


def _select(points: tuple[PointBootstrap, ...], model: WidthModel) -> tuple[PointBootstrap, ...]:
    if model == "inv_n_leave_smallest":
        return points[1:]
    if model == "inv_n_top3":
        if len(points) < 3:
            raise ValueError("inv_n_top3 requires at least three widths")
        return points[-3:]
    if model == "top_width_direct":
        return points[-1:]
    return points


def extrapolate_widths(
    points: Sequence[PointBootstrap],
    *,
    model: WidthModel,
) -> WidthEstimate:
    """Construct one frozen width-limit sensitivity estimate.

    Bootstrap draws are independent across widths but retain the complete
    antithetic pair lineage within each point.  The number of usable draws is
    the minimum available across widths; no resampling is fabricated to pad a
    smaller point.
    """

    all_points = _validate_points(points)
    chosen = _select(all_points, model)
    widths = np.asarray([point.width for point in chosen], dtype=np.float64)
    central_values = np.vstack([point.band.estimate for point in chosen])
    bootstrap_count = min(point.samples.shape[0] for point in chosen)
    confidence = chosen[0].band.confidence

    if model == "top_width_direct":
        central = central_values[-1]
        samples = chosen[-1].samples[:bootstrap_count]
        residual = 0.0
    else:
        if len(chosen) == 1:
            # With only two pilot widths, leave-smallest-out degenerates to the
            # top-width-only sensitivity.  The explicit top-width band is also
            # present in the eventual union, so this cannot narrow the result.
            central = central_values[0]
            samples = chosen[0].samples[:bootstrap_count]
            residual = 0.0
            band = simultaneous_log_band(central, samples, confidence=confidence)
            return WidthEstimate(
                model=model,
                widths_used=(int(widths[0]),),
                output=np.array(chosen[0].output, copy=True),
                band=band,
                samples=samples,
                maximum_relative_fit_residual=residual,
            )
        if model in {"inv_n_all", "inv_n_leave_smallest", "inv_n_top3"}:
            x = np.reciprocal(widths)
        elif model == "inv_sqrt_n_all":
            x = np.reciprocal(np.sqrt(widths))
        else:  # pragma: no cover - protected by the Literal and branches above
            raise ValueError(f"unknown width model {model!r}")
        central, fitted = _fit_intercept(central_values, x)
        residual = float(np.max(
            np.abs(fitted - central_values)
            / np.maximum(np.abs(central_values), np.finfo(float).tiny)
        ))
        sample_cube = np.stack(
            [point.samples[:bootstrap_count] for point in chosen], axis=1
        )  # bootstrap,width,grid
        design = np.column_stack((np.ones(len(x)), x))
        intercept_weights = np.linalg.pinv(design)[0]
        samples = np.einsum("w,bwg->bg", intercept_weights, sample_cube)

    valid = np.all(np.isfinite(samples) & (samples > 0.0), axis=1)
    samples = samples[valid]
    if len(samples) < max(20, int(0.95 * bootstrap_count)):
        raise FloatingPointError("too many width-extrapolated bootstrap curves are nonpositive")
    if np.any(central <= 0.0) or not np.all(np.isfinite(central)):
        raise FloatingPointError("width-extrapolated central kernel is nonpositive")
    band = simultaneous_log_band(central, samples, confidence=confidence)
    return WidthEstimate(
        model=model,
        widths_used=tuple(int(width) for width in widths),
        output=np.array(chosen[0].output, copy=True),
        band=band,
        samples=samples,
        maximum_relative_fit_residual=residual,
    )


def union_width_estimates(
    estimates: Sequence[WidthEstimate],
    *,
    primary_model: WidthModel = "inv_n_all",
) -> UnionWidthReference:
    """Take the nodewise union required by the frozen campaign protocol."""

    estimates = tuple(estimates)
    if not estimates:
        raise ValueError("at least one width estimate is required")
    by_model = {estimate.model: estimate for estimate in estimates}
    if len(by_model) != len(estimates):
        raise ValueError("width-union component models must be unique")
    try:
        primary = by_model[primary_model]
    except KeyError as exc:
        raise ValueError("primary model is absent from the sensitivity union") from exc
    for estimate in estimates[1:]:
        if not np.array_equal(primary.output, estimate.output):
            raise ValueError("width-union components use different output grids")
        if estimate.band.confidence != primary.band.confidence:
            raise ValueError("width-union components use different confidence levels")
    lower = np.min(np.vstack([estimate.band.lower for estimate in estimates]), axis=0)
    upper = np.max(np.vstack([estimate.band.upper for estimate in estimates]), axis=0)
    # The primary central estimator is retained for error summaries, while the
    # lower/upper curves are the full sensitivity union.  Samples are not
    # invented for this non-probabilistic outer envelope.
    band = BootstrapBand(
        estimate=np.array(primary.band.estimate, copy=True),
        lower=lower,
        upper=upper,
        pointwise_log_standard_error=np.array(
            primary.band.pointwise_log_standard_error, copy=True
        ),
        simultaneous_critical_value=primary.band.simultaneous_critical_value,
        confidence=primary.band.confidence,
        valid_replicates=primary.band.valid_replicates,
        attempted_replicates=primary.band.attempted_replicates,
        scale="log_bootstrap_plus_width_sensitivity_union",
    )
    return UnionWidthReference(
        primary_model=primary_model,
        component_models=tuple(estimate.model for estimate in estimates),
        output=np.array(primary.output, copy=True),
        band=band,
    )


def width_sensitivity_summary(estimates: Iterable[WidthEstimate]) -> dict[str, Any]:
    estimates = tuple(estimates)
    if len(estimates) < 2:
        raise ValueError("width sensitivity needs at least two estimators")
    grid = estimates[0].output
    for estimate in estimates[1:]:
        if not np.array_equal(grid, estimate.output):
            raise ValueError("width sensitivity estimators use different grids")
    maximum_log_disagreement = 0.0
    no_common_band_nodes = 0
    for i, left in enumerate(estimates):
        for right in estimates[i + 1 :]:
            maximum_log_disagreement = max(
                maximum_log_disagreement,
                float(np.max(np.abs(np.log(left.band.estimate / right.band.estimate)))),
            )
            overlap = np.maximum(left.band.lower, right.band.lower) <= np.minimum(
                left.band.upper, right.band.upper
            )
            no_common_band_nodes += int(np.count_nonzero(~overlap))
    return {
        "models": [estimate.model for estimate in estimates],
        "maximum_pairwise_log_disagreement": maximum_log_disagreement,
        "pair_node_comparisons_with_disjoint_bands": no_common_band_nodes,
    }


def self_averaging_width_summary(points: Sequence[PointBootstrap]) -> dict[str, Any]:
    """Fit the diagnostic decay of pair variance and estimator SE with width."""

    points = tuple(sorted(points, key=lambda point: point.width))
    if len(points) < 2:
        return {"available": False, "reason": "fewer than two widths"}
    widths = np.asarray([point.width for point in points], dtype=np.float64)
    relative_se = np.asarray([
        float(point.diagnostics["maximum_relative_standard_error"]) for point in points
    ])
    if np.any(~np.isfinite(relative_se)) or np.any(relative_se <= 0.0):
        return {"available": False, "reason": "nonpositive or nonfinite relative SE"}
    slope, intercept = np.polyfit(np.log(widths), np.log(relative_se), 1)
    return {
        "available": True,
        "widths": widths.astype(int).tolist(),
        "maximum_relative_standard_errors": relative_se.tolist(),
        "log_log_slope": float(slope),
        "log_log_intercept": float(intercept),
    }

studies/stieltjes_proxy_campaign/proxy/c:
"""Hitting-time construction of feature, output, and loss proxy curves."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Callable, Iterable

import numpy as np
from scipy.integrate import quad
from scipy.optimize import brentq


MAX_GRID_POINTS = 10_001


def _validate_y(y: float, target: float | None = None) -> float:
    y = float(y)
    if y < 0:
        raise ValueError("output coordinate must be nonnegative")
    if target is not None and y >= target:
        raise ValueError("physical hitting time is finite only below the target")
    return y


def feature_hitting_time(
    kernel: Callable[[float], float],
    y: float,
    *,
    epsabs: float = 1e-11,
    epsrel: float = 1e-11,
) -> float:
    """Return ``int_0^y du/K(u)`` for feature-ascent time."""
    y = _validate_y(y)
    value, error = quad(lambda u: 1.0 / kernel(u), 0.0, y,
                        epsabs=epsabs, epsrel=epsrel, limit=200)
    if not np.isfinite(value) or error > 20 * max(epsabs, epsrel * abs(value)):
        raise ArithmeticError("feature hitting-time quadrature did not meet tolerance")
    return float(value)


def physical_hitting_time(
    kernel: Callable[[float], float],
    y: float,
    *,
    target: float = 1.0,
    epsabs: float = 1e-11,
    epsrel: float = 1e-11,
) -> float:
    """Return ``int_0^y du/[2(target-u)K(u)]`` for squared-loss flow."""
    y = _validate_y(y, target)
    value, error = quad(lambda u: 1.0 / (2.0 * (target - u) * kernel(u)),
                        0.0, y, epsabs=epsabs, epsrel=epsrel, limit=300)
    if not np.isfinite(value) or error > 20 * max(epsabs, epsrel * abs(value)):
        raise ArithmeticError("physical hitting-time quadrature did not meet tolerance")
    return float(value)


def output_at_time(
    kernel: Callable[[float], float],
    time: float,
    *,
    target: float = 1.0,
    y_cap: float = 0.999999,
    epsabs: float = 1e-11,
    epsrel: float = 1e-11,
) -> float:
    """Invert the physical hitting-time map without integrating an ODE."""
    if time < 0:
        raise ValueError("time must be nonnegative")
    if time == 0:
        return 0.0
    upper = target * y_cap
    maximum_time = physical_hitting_time(
        kernel, upper, target=target, epsabs=epsabs, epsrel=epsrel
    )
    if time > maximum_time:
        raise ValueError("requested time exceeds the precommitted output cap")
    return float(brentq(
        lambda y: physical_hitting_time(
            kernel, y, target=target, epsabs=epsabs, epsrel=epsrel
        ) - time,
        0.0,
        upper,
        xtol=max(epsabs, 1e-14),
        rtol=max(epsrel, 4 * np.finfo(float).eps),
        maxiter=100,
    ))


@dataclass(frozen=True)
class HittingCurve:
    output: tuple[float, ...]
    kernel: tuple[float, ...]
    feature_time: tuple[float, ...]
    physical_time: tuple[float, ...]
    loss: tuple[float, ...]


def sample_hitting_curve(
    kernel: Callable[[float], float],
    outputs: Iterable[float],
    *,
    target: float = 1.0,
    max_grid_points: int = MAX_GRID_POINTS,
    epsabs: float = 1e-11,
    epsrel: float = 1e-11,
) -> HittingCurve:
    """Sample a curve on a common output grid, the campaign's primary clock."""
    ys = tuple(float(value) for value in outputs)
    if not ys:
        raise ValueError("output grid must be nonempty")
    if len(ys) > max_grid_points:
        raise ValueError("output grid exceeds the hard point cap")
    if any(right <= left for left, right in zip(ys, ys[1:])):
        raise ValueError("output grid must be strictly increasing")
    for y in ys:
        _validate_y(y, target)
    kernels = tuple(float(kernel(y)) for y in ys)
    if any(value <= 0 or not np.isfinite(value) for value in kernels):
        raise ArithmeticError("kernel curve must remain finite and positive")
    feature = tuple(feature_hitting_time(kernel, y, epsabs=epsabs, epsrel=epsrel)
                    for y in ys)
    physical = tuple(physical_hitting_time(
        kernel, y, target=target, epsabs=epsabs, epsrel=epsrel
    ) for y in ys)
    return HittingCurve(
        output=ys,
        kernel=kernels,
        feature_time=feature,
        physical_time=physical,
        loss=tuple((target - y) ** 2 for y in ys),
    )


@dataclass(frozen=True)
class TimeCurve:
    time: tuple[float, ...]
    output: tuple[float, ...]
    loss: tuple[float, ...]


def sample_time_curve(
    kernel: Callable[[float], float],
    times: Iterable[float],
    *,
    target: float = 1.0,
    y_cap: float = 0.999999,
    max_grid_points: int = MAX_GRID_POINTS,
) -> TimeCurve:
    times_q = tuple(float(value) for value in times)
    if not times_q:
        raise ValueError("time grid must be nonempty")
    if len(times_q) > max_grid_points:
        raise ValueError("time grid exceeds the hard point cap")
    if any(value < 0 for value in times_q):
        raise ValueError("time grid must be nonnegative")
    if any(right <= left for left, right in zip(times_q, times_q[1:])):
        raise ValueError("time grid must be strictly increasing")
    outputs = tuple(output_at_time(
        kernel, time, target=target, y_cap=y_cap
    ) for time in times_q)
    return TimeCurve(
        time=times_q,
        output=outputs,
        loss=tuple((target - y) ** 2 for y in outputs),
    )

studies/stieltjes_proxy_campaign/proxy/e:
"""Small exact formal-series primitives used by the proxy inventory.

All coefficients are :class:`fractions.Fraction`.  The routines are purposely
minimal: they implement only multiplication, composition, reciprocal series,
and reversion around a nonzero linear term.  This keeps the transformation
from accepted MFP jets to output-coordinate moments independently testable.
"""

from __future__ import annotations

from fractions import Fraction
from math import factorial
from typing import Mapping, Sequence


Q = Fraction


def as_fraction(value: int | str | float | Fraction) -> Fraction:
    """Convert a public numeric input without inheriting binary-float noise."""
    if isinstance(value, Fraction):
        return value
    if isinstance(value, bool):
        raise TypeError("booleans are not rational coefficients")
    if isinstance(value, float):
        return Fraction(str(value))
    return Fraction(value)


def pad(series: Sequence[Fraction], degree: int) -> list[Fraction]:
    return list(series[: degree + 1]) + [Q(0)] * max(0, degree + 1 - len(series))


def multiply(
    left: Sequence[Fraction], right: Sequence[Fraction], degree: int
) -> list[Fraction]:
    out = [Q(0) for _ in range(degree + 1)]
    for i, a in enumerate(left):
        if i > degree or not a:
            continue
        for j, b in enumerate(right):
            if i + j > degree:
                break
            if b:
                out[i + j] += a * b
    return out


def compose(
    outer: Sequence[Fraction], inner: Sequence[Fraction], degree: int
) -> list[Fraction]:
    """Return ``outer(inner(x))`` through ``x**degree`` exactly."""
    inner = pad(inner, degree)
    if inner[0]:
        raise ValueError("composition requires an inner series with zero constant")
    out = [Q(0) for _ in range(degree + 1)]
    power = [Q(1)] + [Q(0)] * degree
    for coefficient in outer[: degree + 1]:
        if coefficient:
            for index, value in enumerate(power):
                out[index] += coefficient * value
        power = multiply(power, inner, degree)
    return out


def reciprocal(series: Sequence[Fraction], degree: int) -> list[Fraction]:
    """Return the reciprocal of a series with nonzero constant term."""
    series = pad(series, degree)
    if not series[0]:
        raise ZeroDivisionError("series reciprocal requires nonzero constant")
    out = [Q(0) for _ in range(degree + 1)]
    out[0] = 1 / series[0]
    for n in range(1, degree + 1):
        out[n] = -sum(series[k] * out[n - k] for k in range(1, n + 1)) / series[0]
    return out


def reverse(series: Sequence[Fraction], degree: int) -> list[Fraction]:
    """Reverse ``y=series(x)`` about zero through ``y**degree``."""
    series = pad(series, degree)
    if series[0]:
        raise ValueError("series reversion requires zero constant")
    if not series[1]:
        raise ValueError("series reversion requires nonzero linear coefficient")
    out = [Q(0) for _ in range(degree + 1)]
    out[1] = 1 / series[1]
    for order in range(2, degree + 1):
        # With out[order] temporarily zero, every nonlinear power is already
        # determined.  The missing contribution is series[1]*out[order].
        composed = compose(series, out, order)
        out[order] = -composed[order] / series[1]
    return out


def output_kernel_moments(
    odd_derivatives: Mapping[int, Fraction | int | str],
) -> tuple[Fraction, tuple[Fraction, ...]]:
    """Transform exact odd feature jets into ``K`` baseline and moments.

    ``odd_derivatives[k]`` is ``F^(k)(0)`` for consecutive positive odd
    orders.  If the largest supplied order is ``2m+3``, the return contains
    ``mu_0,...,mu_m`` for

    ``K(y) = K(0) + sum_r (-1)^r mu_r y^(2r+2)``.
    """
    derivatives = {int(k): as_fraction(v) for k, v in odd_derivatives.items()}
    if not derivatives or min(derivatives) != 1:
        raise ValueError("the order-one derivative is required")
    max_order = max(derivatives)
    expected = set(range(1, max_order + 1, 2))
    if set(derivatives) != expected:
        raise ValueError("odd derivatives must be consecutive")
    if not derivatives[1]:
        raise ValueError("F'(0) must be nonzero")

    degree = max_order - 1
    feature = [Q(0) for _ in range(max_order + 1)]
    derivative = [Q(0) for _ in range(degree + 1)]
    for order, value in derivatives.items():
        feature[order] = value / factorial(order)
        derivative[order - 1] = value / factorial(order - 1)

    inverse = reverse(feature, degree)
    kernel = compose(derivative, inverse, degree)
    moments = tuple(
        ((-1) ** r) * kernel[2 * r + 2]
        for r in range((max_order - 1) // 2)
    )
    if any(kernel[k] for k in range(1, degree + 1, 2)):
        raise ArithmeticError("parity regression: transformed kernel is not even")
    return kernel[0], moments


def companion_moments(
    odd_feature_derivatives: Mapping[int, Fraction | int | str],
    even_observable_derivatives: Mapping[int, Fraction | int | str],
) -> tuple[Fraction, tuple[Fraction, ...]]:
    """Transform an even observable to output coordinates exactly.

    For ``N(y)=Q(F^{-1}(y))`` the return is ``N(0)`` and the moments of
    ``(N(sqrt(x))-N(0))/x``.
    """
    f_derivatives = {
        int(k): as_fraction(v) for k, v in odd_feature_derivatives.items()
    }
    q_derivatives = {
        int(k): as_fraction(v) for k, v in even_observable_derivatives.items()
    }
    max_q = max(q_derivatives)
    if set(q_derivatives) != set(range(0, max_q + 1, 2)):
        raise ValueError("even observable derivatives must be consecutive")
    if max(f_derivatives) < max_q + 1:
        raise ValueError("feature jet must extend one order beyond observable jet")

    feature = [Q(0) for _ in range(max_q + 2)]
    for order, value in f_derivatives.items():
        if order <= max_q + 1:
            feature[order] = value / factorial(order)
    inverse = reverse(feature, max_q)
    observable = [Q(0) for _ in range(max_q + 1)]
    for order, value in q_derivatives.items():
        observable[order] = value / factorial(order)
    transformed = compose(observable, inverse, max_q)
    moments = tuple(
        ((-1) ** r) * transformed[2 * r + 2]
        for r in range(max_q // 2)
    )
    if any(transformed[k] for k in range(1, max_q + 1, 2)):
        raise ArithmeticError("parity regression: transformed observable is not even")
    return transformed[0], moments

studies/stieltjes_proxy_campaign/proxy/h:
"""Conditional Stieltjes rational hierarchy built one exact moment at a time."""

from __future__ import annotations

from dataclasses import dataclass
from fractions import Fraction
from math import log
from typing import Iterable, Literal, Sequence

import numpy as np
import sympy as sp

from .exact_series import as_fraction, reciprocal


Side = Literal["lower", "upper"]


class MomentConeError(ValueError):
    """Raised when a supplied prefix cannot define a positive S-fraction."""


def stieltjes_s_fraction(
    moments: Sequence[Fraction | int | str | float],
) -> tuple[Fraction, ...]:
    """Return exact S-fraction coefficients ``beta_1,...``.

    For ``R(x)=sum (-1)^r mu_r x^r`` the convention is

    ``R(x)=mu_0/(1+beta_1*x/(1+beta_2*x/(...)))``.

    A strictly positive Stieltjes prefix produces positive beta coefficients.
    The identically zero measure is represented by an empty tuple.  Signed or
    inconsistent inputs fail closed rather than silently yielding a rational
    curve with no Stieltjes ordering theorem.
    """
    mu = tuple(as_fraction(value) for value in moments)
    if not mu:
        return ()
    if mu[0] < 0:
        raise MomentConeError("mu_0 is negative")
    if mu[0] == 0:
        if any(mu[1:]):
            raise MomentConeError("zero mass with nonzero higher moments")
        return ()

    tail = [(((-1) ** r) * value) / mu[0] for r, value in enumerate(mu)]
    betas: list[Fraction] = []
    while len(tail) > 1:
        inverse = reciprocal(tail, len(tail) - 1)
        quotient = inverse[1:]
        beta = quotient[0]
        if beta < 0:
            raise MomentConeError(f"negative S-fraction coefficient beta_{len(betas)+1}")
        if beta == 0:
            if any(quotient[1:]):
                raise MomentConeError("zero S-fraction coefficient with nonzero tail")
            break
        betas.append(beta)
        tail = [value / beta for value in quotient]
    return tuple(betas)


def _continued_fraction_value(mu0: float, betas: Sequence[float], x: float) -> float:
    denominator = 1.0
    for beta in reversed(betas):
        denominator = 1.0 + beta * x / denominator
    return mu0 / denominator


def _continued_fraction_exact(
    mu0: Fraction, betas: Sequence[Fraction], x: Fraction
) -> Fraction:
    denominator = Fraction(1)
    for beta in reversed(betas):
        denominator = 1 + beta * x / denominator
    return mu0 / denominator


@dataclass(frozen=True)
class KernelApproximation:
    """One conditional rational kernel approximation."""

    name: str
    baseline: Fraction
    information_moments: int
    side: Side
    mu0: Fraction | None
    betas: tuple[Fraction, ...] = ()

    def resolvent(self, x: float) -> float:
        if x < 0:
            raise ValueError("the Stieltjes proxy is restricted to x >= 0")
        if self.mu0 is None:
            return 0.0
        return _continued_fraction_value(
            float(self.mu0), tuple(float(beta) for beta in self.betas), float(x)
        )

    def resolvent_exact(self, x: Fraction | int | str) -> Fraction:
        xq = as_fraction(x)
        if xq < 0:
            raise ValueError("the Stieltjes proxy is restricted to x >= 0")
        if self.mu0 is None:
            return Fraction(0)
        return _continued_fraction_exact(self.mu0, self.betas, xq)

    def kernel(self, y: float) -> float:
        return float(self.baseline) + y * y * self.resolvent(y * y)

    def kernel_exact(self, y: Fraction | int | str) -> Fraction:
        yq = as_fraction(y)
        return self.baseline + yq * yq * self.resolvent_exact(yq * yq)


@dataclass(frozen=True)
class TaylorKernelApproximation:
    """Equal-information raw Taylor control; it carries no global ordering."""

    baseline: Fraction
    moments: tuple[Fraction, ...]

    @property
    def information_moments(self) -> int:
        return len(self.moments)

    @property
    def name(self) -> str:
        return f"taylor_{len(self.moments)}moments_unordered"

    def kernel(self, y: float) -> float:
        x = y * y
        resolvent = sum(((-1.0) ** r) * float(mu) * x**r
                        for r, mu in enumerate(self.moments))
        return float(self.baseline) + x * resolvent


@dataclass(frozen=True)
class KernelBracket:
    """Best lower/upper pair available after a given moment prefix."""

    information_moments: int
    lower: KernelApproximation
    upper: KernelApproximation

    def log_width(self, y: float) -> float:
        lower = self.lower.kernel(y)
        upper = self.upper.kernel(y)
        if lower <= 0 or upper <= 0:
            raise ValueError("logarithmic width requires positive kernels")
        return log(upper / lower)


def build_kernel_hierarchy(
    baseline: Fraction | int | str | float,
    moments: Sequence[Fraction | int | str | float],
) -> tuple[KernelApproximation, ...]:
    """Build NTK and every one-moment-at-a-time S-fraction convergent."""
    baseline_q = as_fraction(baseline)
    if baseline_q <= 0:
        raise ValueError("kernel baseline must be positive")
    mu = tuple(as_fraction(value) for value in moments)
    ntk = KernelApproximation(
        name="ntk_0moments_lower",
        baseline=baseline_q,
        information_moments=0,
        side="lower",
        mu0=None,
    )
    if not mu or (mu[0] == 0 and not any(mu[1:])):
        return (ntk,)
    betas = stieltjes_s_fraction(mu)
    levels: list[KernelApproximation] = [ntk]
    for count in range(1, len(mu) + 1):
        needed_betas = count - 1
        if needed_betas > len(betas):
            # A terminating finite-support fraction is already exact; further
            # redundant moments do not define a new level.
            break
        side: Side = "upper" if count % 2 else "lower"
        if side == "upper":
            nodes = (count + 1) // 2
            name = f"zero_radau_{nodes}node_{count}moments_upper"
        else:
            nodes = count // 2
            name = f"gauss_{nodes}node_{count}moments_lower"
        levels.append(KernelApproximation(
            name=name,
            baseline=baseline_q,
            information_moments=count,
            side=side,
            mu0=mu[0],
            betas=betas[:needed_betas],
        ))
    return tuple(levels)


def build_kernel_brackets(
    baseline: Fraction | int | str | float,
    moments: Sequence[Fraction | int | str | float],
) -> tuple[KernelBracket, ...]:
    """Return the nested conditional envelope after every usable moment."""
    hierarchy = build_kernel_hierarchy(baseline, moments)
    lower = hierarchy[0]
    upper: KernelApproximation | None = None
    brackets: list[KernelBracket] = []
    for approximation in hierarchy[1:]:
        if approximation.side == "lower":
            lower = approximation
        else:
            upper = approximation
        if upper is not None:
            brackets.append(KernelBracket(
                information_moments=approximation.information_moments,
                lower=lower,
                upper=upper,
            ))
    return tuple(brackets)


def build_taylor_controls(
    baseline: Fraction | int | str | float,
    moments: Sequence[Fraction | int | str | float],
) -> tuple[TaylorKernelApproximation, ...]:
    baseline_q = as_fraction(baseline)
    mu = tuple(as_fraction(value) for value in moments)
    return tuple(
        TaylorKernelApproximation(baseline_q, mu[:count])
        for count in range(1, len(mu) + 1)
    )


@dataclass(frozen=True)
class AtomicQuadrature:
    """Numerical nodes/weights plus the exact monic node polynomial."""

    kind: Literal["gauss", "zero_radau"]
    nodes: tuple[float, ...]
    weights: tuple[float, ...]
    monic_polynomial_ascending: tuple[Fraction, ...]

    def resolvent(self, x: float) -> float:
        return sum(weight / (1.0 + node * x)
                   for node, weight in zip(self.nodes, self.weights, strict=True))


def _sympy_rational(value: Fraction) -> sp.Rational:
    return sp.Rational(value.numerator, value.denominator)


def gaussian_quadrature(
    moments: Sequence[Fraction | int | str | float],
) -> AtomicQuadrature:
    """Construct the Gaussian rule from exactly ``2n`` moments."""
    mu = tuple(as_fraction(value) for value in moments)
    if not mu or len(mu) % 2:
        raise ValueError("Gaussian quadrature requires exactly 2n moments")
    n = len(mu) // 2
    hankel = sp.Matrix([
        [_sympy_rational(mu[i + j]) for j in range(n)]
        for i in range(n)
    ])
    right = sp.Matrix([-_sympy_rational(mu[i + n]) for i in range(n)])
    try:
        lower = hankel.inv() * right
    except Exception as exc:  # pragma: no cover - SymPy exception class varies
        raise MomentConeError("singular Gaussian moment matrix") from exc
    coefficients = tuple(
        Fraction(int(value.p), int(value.q)) for value in lower
    ) + (Fraction(1),)
    variable = sp.symbols("t")
    polynomial = sum(_sympy_rational(value) * variable**power
                     for power, value in enumerate(coefficients))
    roots = sp.nroots(polynomial, n=50, maxsteps=200)
    nodes: list[float] = []
    for root in roots:
        real, imag = float(sp.re(root)), float(sp.im(root))
        if abs(imag) > 1e-30:
            raise MomentConeError("Gaussian node polynomial has a nonreal root")
        if real < -1e-14:
            raise MomentConeError("Gaussian node polynomial has a negative root")
        nodes.append(max(0.0, real))
    nodes.sort()
    vandermonde = np.array([[node**power for node in nodes]
                            for power in range(n)], dtype=np.float64)
    weights = np.linalg.solve(vandermonde, np.array([float(value) for value in mu[:n]]))
    if np.min(weights) < -1e-12:
        raise MomentConeError("Gaussian quadrature has a negative weight")
    return AtomicQuadrature(
        kind="gauss",
        nodes=tuple(nodes),
        weights=tuple(float(max(0.0, value)) for value in weights),
        monic_polynomial_ascending=coefficients,
    )


def zero_radau_quadrature(
    moments: Sequence[Fraction | int | str | float],
) -> AtomicQuadrature:
    """Construct the zero-Radau rule from exactly ``2n+1`` moments."""
    mu = tuple(as_fraction(value) for value in moments)
    if not mu or len(mu) % 2 != 1:
        raise ValueError("zero-Radau quadrature requires exactly 2n+1 moments")
    if len(mu) == 1:
        return AtomicQuadrature(
            kind="zero_radau",
            nodes=(0.0,),
            weights=(float(mu[0]),),
            monic_polynomial_ascending=(Fraction(0), Fraction(1)),
        )
    shifted = gaussian_quadrature(mu[1:])
    if any(node <= 0 for node in shifted.nodes):
        raise MomentConeError("zero-Radau positive nodes must be strictly positive")
    positive_weights = tuple(weight / node for node, weight in zip(
        shifted.nodes, shifted.weights, strict=True
    ))
    zero_weight = float(mu[0]) - sum(positive_weights)
    if zero_weight < -1e-11:
        raise MomentConeError("zero-Radau rule has a negative zero-node weight")
    coefficients = (Fraction(0),) + shifted.monic_polynomial_ascending
    return AtomicQuadrature(
        kind="zero_radau",
        nodes=(0.0,) + shifted.nodes,
        weights=(max(0.0, zero_weight),) + positive_weights,
        monic_polynomial_ascending=coefficients,
    )


def quadrature_for_prefix(
    moments: Sequence[Fraction | int | str | float],
) -> AtomicQuadrature:
    """Return the Gaussian/even or zero-Radau/odd prefix rule."""
    return (zero_radau_quadrature(moments) if len(moments) % 2
            else gaussian_quadrature(moments))


def quadrature_moment_errors(
    rule: AtomicQuadrature,
    moments: Iterable[Fraction | int | str | float],
) -> tuple[float, ...]:
    return tuple(
        sum(weight * node**order for node, weight in zip(
            rule.nodes, rule.weights, strict=True
        )) - float(as_fraction(target))
        for order, target in enumerate(moments)
    )

studies/stieltjes_proxy_campaign/proxy/i:
"""Exact inventory of every accepted family usable by the proxy campaign.

The evaluators read the checked artifacts in place and transform their jets
with exact rational arithmetic.  They do not copy large coefficient tables,
fit trajectories, or inspect any future finite-width result.
"""

from __future__ import annotations

import ast
from dataclasses import dataclass
from fractions import Fraction
from functools import lru_cache
import hashlib
import json
from pathlib import Path
from typing import Callable, Mapping

from .exact_series import (
    as_fraction,
    companion_moments,
    output_kernel_moments,
)


REPO_ROOT = Path(__file__).resolve().parents[3]
COMPILER = REPO_ROOT / "studies/mfp_quadratic_compiler"
COMPILER_DATA = REPO_ROOT / "data/historical/studies/mfp_quadratic_compiler"
THEORY = REPO_ROOT / "studies/stieltjes_theory_history"


@dataclass(frozen=True)
class EvaluatedFamily:
    key: str
    observable: str
    baseline: Fraction
    moments: tuple[Fraction, ...]
    parameters: tuple[tuple[str, Fraction], ...]
    drives_training: bool
    training_target: Fraction | None
    coordinate_scope: str
    source_paths: tuple[str, ...]
    source_sha256: tuple[str, ...]
    caveats: tuple[str, ...] = ()

    def exact_record(self) -> dict:
        return {
            "key": self.key,
            "observable": self.observable,
            "baseline": str(self.baseline),
            "moments": [str(value) for value in self.moments],
            "parameters": {name: str(value) for name, value in self.parameters},
            "drives_training": self.drives_training,
            "training_target": (
                None if self.training_target is None else str(self.training_target)
            ),
            "coordinate_scope": self.coordinate_scope,
            "source_paths": list(self.source_paths),
            "source_sha256": list(self.source_sha256),
            "caveats": list(self.caveats),
        }


@dataclass(frozen=True)
class FamilySpec:
    key: str
    title: str
    observable: str
    parameters: tuple[str, ...]
    exact_domain: str
    moment_count: int
    drives_training: bool
    target_rule: Callable[[Mapping[str, Fraction]], Fraction | None]
    coordinate_scope: str
    source_paths: tuple[Path, ...]
    evaluator: Callable[[Mapping[str, Fraction]], tuple[Fraction, tuple[Fraction, ...], tuple[str, ...]]]

    def public_record(self) -> dict:
        return {
            "key": self.key,
            "title": self.title,
            "observable": self.observable,
            "parameters": list(self.parameters),
            "exact_domain": self.exact_domain,
            "moment_count": self.moment_count,
            "hierarchy_levels_including_ntk": self.moment_count + 1,
            "drives_training": self.drives_training,
            "training_target_rule": (
                "parameter-dependent; inspect evaluate_family"
                if self.key == "variance_homotopy"
                else "1" if self.drives_training else "use the associated output kernel"
            ),
            "coordinate_scope": self.coordinate_scope,
            "source_paths": [str(path.relative_to(REPO_ROOT)) for path in self.source_paths],
        }


@lru_cache(maxsize=None)
def _json(path: Path) -> dict:
    return json.loads(path.read_text(encoding="utf-8"))


def _sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _poly(coefficients: list[str] | tuple[int, ...], x: Fraction) -> Fraction:
    value = Fraction(0)
    for coefficient in reversed(coefficients):
        value = value * x + as_fraction(coefficient)
    return value


def _require(parameters: Mapping[str, Fraction], names: tuple[str, ...]) -> tuple[Fraction, ...]:
    missing = set(names) - set(parameters)
    extra = set(parameters) - set(names)
    if missing or extra:
        raise ValueError(f"parameter mismatch: missing={sorted(missing)}, extra={sorted(extra)}")
    return tuple(parameters[name] for name in names)


def _canonical(_: Mapping[str, Fraction]) -> tuple[Fraction, tuple[Fraction, ...], tuple[str, ...]]:
    document = _json(THEORY / "certificates_order11.json")
    return (
        as_fraction(document["kappa_K_even_coefficients"][0]),
        tuple(as_fraction(value) for value in document["mu"]),
        (),
    )


@lru_cache(maxsize=1)
def _variance_rows() -> tuple[tuple[int, ...], ...]:
    """Read the accepted Wick-sector matrix without executing its module."""
    path = THEORY / "sector_total_nonnegativity.py"
    tree = ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    for node in tree.body:
        if isinstance(node, ast.Assign) and any(
            isinstance(target, ast.Name) and target.id == "C" for target in node.targets
        ):
            value = ast.literal_eval(node.value)
            return tuple(tuple(int(entry) for entry in row) for row in value)
    raise RuntimeError("accepted sector matrix C was not found")


def _variance(parameters: Mapping[str, Fraction]) -> tuple[Fraction, tuple[Fraction, ...], tuple[str, ...]]:
    (alpha,) = _require(parameters, ("alpha",))
    if alpha < 0:
        raise ValueError("variance alpha must be nonnegative")
    # C[r][p] is [alpha^(p+1)] F_alpha^(2r+1).  Dividing F by
    # alpha makes the normalized derivative sum_p C[r][p] alpha^p.
    derivatives = {
        2 * r + 1: _poly(list(row), alpha)
        for r, row in enumerate(_variance_rows())
    }
    baseline, moments = output_kernel_moments(derivatives)
    return baseline, moments, (
        "This is the normalized kernel kappa_alpha(z)=K_alpha(alpha*z)/alpha.",
        "For alpha>0, physical label one is the normalized target z*=1/alpha; at alpha=0 there is no finite physical target in this chart.",
        "At alpha=0 it is the exact singular Lambert-W calibration boundary; at alpha=1 it is canonical.",
    )


def _campaign1_jets(observable: str, lam: Fraction) -> dict[int, Fraction]:
    path = COMPILER_DATA / "campaign1/results_order9_q2_order8.json"
    records = _json(path)["observables"][observable]["jets"]
    return {
        int(record["order"]): _poly(record["lambda_coefficients"], lam)
        for record in records
    }


def _relative_metric_output(parameters: Mapping[str, Fraction]):
    (lam,) = _require(parameters, ("lambda",))
    if lam < 0:
        raise ValueError("metric lambda must be nonnegative")
    jets = _campaign1_jets("f", lam)
    return (*output_kernel_moments({k: v for k, v in jets.items() if k % 2}), ())


def _relative_metric_q2(parameters: Mapping[str, Fraction]):
    (lam,) = _require(parameters, ("lambda",))
    if lam < 0:
        raise ValueError("metric lambda must be nonnegative")
    feature = _campaign1_jets("f", lam)
    q2 = _campaign1_jets("q2", lam)
    baseline, moments = companion_moments(
        {k: v for k, v in feature.items() if k % 2},
        {k: v for k, v in q2.items() if k % 2 == 0},
    )
    return baseline, moments, (
        "This is the independent second-hidden companion N2, not a training kernel.",
        "The first-hidden Q1 curve is derived directly from the output kernel and is not an independent family.",
    )


def _two_input(channel: str, parameters: Mapping[str, Fraction]):
    (t,) = _require(parameters, ("t",))
    if not 0 <= t <= 1:
        raise ValueError("two-input t=theta^2 must lie in [0,1]")
    document = _json(COMPILER / "campaign2/certificates_order7.json")
    key = "plus" if channel == "plus" else "minus_raw"
    if channel == "minus" and t == 1:
        raise ValueError(
            "the physical opposite-label channel collapses at t=1; its normalized h extension is not a physical target-one flow"
        )
    derivatives = {
        int(order): _poly(coefficients, t)
        for order, coefficients in document["jets"][key].items()
    }
    baseline, moments = output_kernel_moments(derivatives)
    caveats = () if channel == "plus" else (
        "These are raw physical-channel moments, not the normalized h moments used to certify the singular t=1 endpoint.",
        "The admissible physical domain is 0 <= t < 1.",
    )
    return baseline, moments, caveats


def _centered(parameters: Mapping[str, Fraction]):
    (c,) = _require(parameters, ("c",))
    if not 0 <= c <= 2:
        raise ValueError("centering c must lie in [0,2]")
    t = 1 - c
    document = _json(COMPILER / "campaign3/certificates_order7.json")
    derivatives = {
        int(order): _poly(coefficients, t)
        for order, coefficients in document["jets_t"].items()
    }
    return (*output_kernel_moments(derivatives), ())


def _block_metric(parameters: Mapping[str, Fraction]):
    alpha, beta = _require(parameters, ("alpha", "beta"))
    if alpha < 0 or beta < 0:
        raise ValueError("block metrics alpha,beta must be nonnegative")
    document = _json(COMPILER_DATA / "campaign4/results_order9.json")
    derivatives: dict[int, Fraction] = {}
    for record in document["jets"]:
        order = int(record["order"])
        if order % 2 == 0:
            continue
        derivatives[order] = sum(
            as_fraction(term["value"])
            * alpha ** int(term["alpha_power"])
            * beta ** int(term["beta_power"])
            for term in record["monomials"]
        )
    return (*output_kernel_moments(derivatives), ())


def _three_input(parameters: Mapping[str, Fraction]):
    (rho,) = _require(parameters, ("rho",))
    if not Fraction(-1, 2) <= rho <= 1:
        raise ValueError("three-input equicorrelation rho must lie in [-1/2,1]")
    document = _json(
        COMPILER_DATA / "campaign5_b3/frozen/stage_b_connected_order5.json"
    )
    derivatives = {
        order: _poly(coefficients, rho) / (3 ** (order + 1))
        for order, coefficients in enumerate(document["raw_rho"])
        if order % 2 == 1
    }
    baseline, moments = output_kernel_moments(derivatives)
    return baseline, moments, (
        "Only mu_0 and mu_1 are available; no ordinary 2x2 Hankel test exists for this family.",
    )


def _specs() -> tuple[FamilySpec, ...]:
    canonical_certificate = THEORY / "certificates_order11.json"
    sector_source = THEORY / "sector_total_nonnegativity.py"
    variance_audit = THEORY / "finite_variance_hankel_audit.py"
    boundary_audit = THEORY / "variance_homotopy_boundary_audit.py"
    c1_results = COMPILER_DATA / "campaign1/results_order9_q2_order8.json"
    c1_certificate = COMPILER / "campaign1/hankel_certificates_order9_q2_order8.json"
    c2_certificate = COMPILER / "campaign2/certificates_order7.json"
    c3_certificate = COMPILER / "campaign3/certificates_order7.json"
    c4_results = COMPILER_DATA / "campaign4/results_order9.json"
    c4_certificate = COMPILER / "campaign4/certificates_order9.json"
    c5_results = COMPILER_DATA / "campaign5_b3/frozen/stage_b_connected_order5.json"
    c5_certificate = COMPILER / "campaign5_b3/certificates_lower_moments.json"
    return (
        FamilySpec(
            "canonical", "Canonical one-input kernel", "K", (), "singleton", 5,
            True, lambda _: Fraction(1), "physical output y", (canonical_certificate,), _canonical,
        ),
        FamilySpec(
            "variance_homotopy", "Normalized middle-weight variance homotopy", "kappa_alpha",
            ("alpha",), "alpha >= 0", 5, True,
            lambda p: None if p["alpha"] == 0 else 1 / p["alpha"],
            "normalized output z=y/alpha",
            (sector_source, variance_audit, boundary_audit), _variance,
        ),
        FamilySpec(
            "relative_metric_output", "Relative block-metric ray", "K_lambda",
            ("lambda",), "lambda >= 0", 4, True, lambda _: Fraction(1), "physical output y",
            (c1_results, c1_certificate), _relative_metric_output,
        ),
        FamilySpec(
            "relative_metric_q2", "Second-hidden companion on the metric ray", "N2_lambda",
            ("lambda",), "lambda >= 0", 4, False, lambda _: None, "physical output y",
            (c1_results, c1_certificate), _relative_metric_q2,
        ),
        FamilySpec(
            "two_input_equal", "Two-input equal-label channel", "K_plus",
            ("t",), "0 <= t=theta^2 <= 1", 3, True, lambda _: Fraction(1), "symmetry-channel output g_plus",
            (c2_certificate,), lambda p: _two_input("plus", p),
        ),
        FamilySpec(
            "two_input_opposite", "Two-input opposite-label physical channel", "K_minus",
            ("t",), "0 <= t=theta^2 < 1", 3, True, lambda _: Fraction(1), "symmetry-channel output g_minus",
            (c2_certificate,), lambda p: _two_input("minus", p),
        ),
        FamilySpec(
            "centered_activation", "Centered first-hidden quadratic activation", "K_c",
            ("c",), "0 <= c <= 2", 3, True, lambda _: Fraction(1), "physical output y",
            (c3_certificate,), _centered,
        ),
        FamilySpec(
            "independent_block_metric", "Independent hidden-block metric quadrant", "K_alpha_beta",
            ("alpha", "beta"), "alpha,beta >= 0", 4, True, lambda _: Fraction(1), "physical output y",
            (c4_results, c4_certificate), _block_metric,
        ),
        FamilySpec(
            "three_input_equal", "Three-input equal-label equicorrelation channel", "K_3",
            ("rho",), "-1/2 <= rho <= 1", 2, True, lambda _: Fraction(1), "symmetric output g_3",
            (c5_results, c5_certificate), _three_input,
        ),
    )


@lru_cache(maxsize=1)
def _spec_by_key() -> dict[str, FamilySpec]:
    return {spec.key: spec for spec in _specs()}


def family_inventory() -> tuple[dict, ...]:
    """Return immutable public metadata, not an exploratory parameter grid."""
    return tuple(spec.public_record() for spec in _specs())


def evaluate_family(
    key: str, **parameters: int | str | float | Fraction
) -> EvaluatedFamily:
    """Evaluate one preselected rational parameter point exactly."""
    try:
        spec = _spec_by_key()[key]
    except KeyError as exc:
        raise KeyError(f"unknown proxy family {key!r}") from exc
    rational_parameters = {name: as_fraction(value) for name, value in parameters.items()}
    baseline, moments, caveats = spec.evaluator(rational_parameters)
    if len(moments) != spec.moment_count:
        raise ArithmeticError(
            f"{key} produced {len(moments)} moments, expected {spec.moment_count}"
        )
    paths = spec.source_paths
    return EvaluatedFamily(
        key=key,
        observable=spec.observable,
        baseline=baseline,
        moments=moments,
        parameters=tuple((name, rational_parameters[name]) for name in spec.parameters),
        drives_training=spec.drives_training,
        training_target=spec.target_rule(rational_parameters),
        coordinate_scope=spec.coordinate_scope,
        source_paths=tuple(str(path.relative_to(REPO_ROOT)) for path in paths),
        source_sha256=tuple(_sha256(path) for path in paths),
        caveats=caveats,
    )

